<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Application,Program,SiteContent};use Illuminate\Http\{JsonResponse,Request};use Illuminate\Support\Facades\Storage;use Illuminate\View\View;use Symfony\Component\HttpFoundation\StreamedResponse;
class ApplicationController extends Controller{public function index(Request $request):JsonResponse{$filters=$request->validate(['program_id'=>'nullable|integer|exists:programs,id','year'=>'nullable|integer|min:2000|max:'.(date('Y')+1)]);$query=Application::with('program:id,name')->when($filters['program_id']??null,fn($q,$id)=>$q->where('program_id',$id))->when($filters['year']??null,fn($q,$year)=>$q->whereYear('submitted_at',$year));$page=$query->latest('submitted_at')->paginate(20)->withQueryString();$page->setCollection($page->getCollection()->map(fn($x)=>array_merge($x->toArray(),['name'=>$x->first_name.' '.$x->last_name,'program'=>$x->program->name])));return response()->json(['data'=>$page,'filters'=>['programs'=>Program::orderBy('name')->get(['id','name']),'years'=>Application::selectRaw('YEAR(submitted_at) as year')->distinct()->orderByDesc('year')->pluck('year')]]);}public function update(Request $r,Application $application):JsonResponse{$application->update($r->validate(['status'=>'required|in:submitted,under_review,shortlisted,accepted,rejected','admin_notes'=>'nullable|string|max:3000']));return response()->json(['data'=>$application]);}public function printView(Application $application):View{$application->load('program:id,name,duration');$collegeName=SiteContent::where('key','college_name')->value('value')?:'College of Nursing';return view('admin.application-print',compact('application','collegeName'));}public function document(Application $application,string $type):StreamedResponse{$path=match($type){'transcript'=>$application->transcript_path,'identity'=>$application->identity_document_path,default=>abort(404)};abort_unless(Storage::disk('local')->exists($path),404);return Storage::disk('local')->download($path,$application->reference.'-'.$type.'.'.pathinfo($path,PATHINFO_EXTENSION));}}
